# 成功率指标
- name: success-rate
  query: |
    sum(rate(http_requests_total{
      deployment="my-app-canary",
      status=~"2..|3.."
    }[5m])) /
    sum(rate(http_requests_total{
      deployment="my-app-canary"
    }[5m]))
  threshold: ">= 0.99"

# 错误率指标
- name: error-rate
  query: |
    sum(rate(http_requests_total{
      deployment="my-app-canary",
      status=~"5.."
    }[5m])) /
    sum(rate(http_requests_total{
      deployment="my-app-canary"
    }[5m]))
  threshold: "<= 0.01"

# P99 延迟
- name: latency-p99
  query: |
    histogram_quantile(0.99,
      sum(rate(http_request_duration_seconds_bucket{
        deployment="my-app-canary"
      }[5m])) by (le)
    )
  threshold: "<= 0.5"

# CPU 使用率
- name: cpu-utilization
  query: |
    avg(rate(container_cpu_usage_seconds_total{
      pod=~"my-app-canary.*"
    }[5m])) /
    avg(kube_pod_container_resource_limits{
      pod=~"my-app-canary.*",
      resource="cpu"
    })
  threshold: "<= 0.8"

# 内存饱和度
- name: memory-saturation
  query: |
    avg(container_memory_working_set_bytes{
      pod=~"my-app-canary.*"
    }) /
    avg(kube_pod_container_resource_limits{
      pod=~"my-app-canary.*",
      resource="memory"
    })
  threshold: "<= 0.85"

# Pod 重启次数
- name: pod-restarts
  query: |
    sum(increase(kube_pod_container_status_restarts_total{
      pod=~"my-app-canary.*"
    }[10m]))
  threshold: "== 0"

- name: db-connection-saturation
  query: |
    max(db_connection_pool_active{
      deployment="my-app-canary"
    }) /
    max(db_connection_pool_max{
      deployment="my-app-canary"
    })
  threshold: "<= 0.9"
  failureLimit: 0  # 不允许任何超限

# 监控上游重试率
- name: upstream-retry-rate
  query: |
    sum(rate(http_client_requests_total{
      caller="upstream-service",
      callee="my-app-canary",
      retry="true"
    }[5m])) /
    sum(rate(http_client_requests_total{
      caller="upstream-service",
      callee="my-app-canary"
    }[5m]))
  threshold: "<= 0.05"  # 重试率 < 5%
